    t.del_flag = '0'
     AND t.transfer_no LIKE CONCAT('%', #{transferNo}, '%')
     AND t.work_order_no LIKE CONCAT('%', #{workOrderNo}, '%')
     AND t.wip_no LIKE CONCAT('%', #{wipNo}, '%')
